CREATE    PROCEDURE [synapse_ce].[usp_Update_apuk_accreditedprogramme]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_accreditationcontactid] = stg.[apuk_accreditationcontactid],
		tgt.[apuk_accreditationcontactid_entitytype] = stg.[apuk_accreditationcontactid_entitytype],
		tgt.[apuk_accreditationcontactidname] = stg.[apuk_accreditationcontactidname],
		tgt.[apuk_accreditationcontactidyominame] = stg.[apuk_accreditationcontactidyominame],
		tgt.[apuk_accreditedprogrammeid] = stg.[apuk_accreditedprogrammeid],
		tgt.[apuk_amrduedate] = stg.[apuk_amrduedate],
		tgt.[apuk_conditions] = stg.[apuk_conditions],
		tgt.[apuk_deliverymethod] = stg.[apuk_deliverymethod],
		tgt.[apuk_departmentid] = stg.[apuk_departmentid],
		tgt.[apuk_departmentid_entitytype] = stg.[apuk_departmentid_entitytype],
		tgt.[apuk_departmentidname] = stg.[apuk_departmentidname],
		tgt.[apuk_displayonweb] = stg.[apuk_displayonweb],
		tgt.[apuk_durationyears] = stg.[apuk_durationyears],
		tgt.[apuk_enddate] = stg.[apuk_enddate],
		tgt.[apuk_endmonth] = stg.[apuk_endmonth],
		tgt.[apuk_endyear] = stg.[apuk_endyear],
		tgt.[apuk_level] = stg.[apuk_level],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_reaccreditationapplication] = stg.[apuk_reaccreditationapplication],
		tgt.[apuk_staffnotes] = stg.[apuk_staffnotes],
		tgt.[apuk_startdate] = stg.[apuk_startdate],
		tgt.[apuk_startmonth] = stg.[apuk_startmonth],
		tgt.[apuk_startyear] = stg.[apuk_startyear],
		tgt.[apuk_status] = stg.[apuk_status],
		tgt.[apuk_universityid] = stg.[apuk_universityid],
		tgt.[apuk_universityid_entitytype] = stg.[apuk_universityid_entitytype],
		tgt.[apuk_universityidname] = stg.[apuk_universityidname],
		tgt.[apuk_universityidyominame] = stg.[apuk_universityidyominame],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[organizationid] = stg.[organizationid],
		tgt.[organizationid_entitytype] = stg.[organizationid_entitytype],
		tgt.[organizationidname] = stg.[organizationidname],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM [synapse_ce].[apuk_accreditedprogramme] tgt
		INNER JOIN [staging_ce].[apuk_accreditedprogramme] stg
			ON tgt.[id] = stg.[id]
END
